SELECT      th.TSF_NO                                           AS transfer_no,     th.TSF_TYPE                                         AS transfer_type,     CASE th.TSF_TYPE         WHEN 'ST'  THEN 'Store Order'         WHEN 'MR'  THEN 'Manual Requisition'         WHEN 'RQ'  THEN 'Replenishment'         WHEN 'EG'  THEN 'Externally Generated'         WHEN 'CO'  THEN 'Customer Order'         ELSE th.TSF_TYPE     END                                                 AS transfer_type_desc,     th.STATUS                                           AS transfer_status,     CASE th.STATUS         WHEN 'A'  THEN 'Approved - Not Shipped'         WHEN 'S'  THEN 'Shipped - Awaiting Receipt'         WHEN 'IR' THEN 'In Progress (Partial Receipt)'         ELSE th.STATUS     END                                                 AS status_desc,       th.DELIVERY_DATE                                    AS expected_delivery_date,     th.CREATE_DATE                                      AS transfer_create_date,     TRUNC(SYSDATE) - TRUNC(th.DELIVERY_DATE)           AS days_overdue,     CASE         WHEN TRUNC(SYSDATE) - TRUNC(th.DELIVERY_DATE) BETWEEN 1  AND 7              THEN '1 - 7 Days'         WHEN TRUNC(SYSDATE) - TRUNC(th.DELIVERY_DATE) BETWEEN 8  AND 14              THEN '8 - 14 Days'         WHEN TRUNC(SYSDATE) - TRUNC(th.DELIVERY_DATE) BETWEEN 15 AND 30              THEN '15 - 30 Days'         WHEN TRUNC(SYSDATE) - TRUNC(th.DELIVERY_DATE) > 30              THEN '30+ Days'     END                                                 AS overdue_aging_bucket,       th.FROM_LOC                                         AS from_location_id,     th.FROM_LOC_TYPE                                    AS from_loc_type,     CASE th.FROM_LOC_TYPE         WHEN 'S' THEN fs.STORE_NAME         WHEN 'W' THEN fw.WH_NAME     END                                                 AS from_location_name,       th.TO_LOC                                           AS to_location_id,     th.TO_LOC_TYPE                                      AS to_loc_type,     CASE th.TO_LOC_TYPE         WHEN 'S' THEN ts.STORE_NAME         WHEN 'W' THEN tw.WH_NAME     END                                                 AS to_location_name,       td.ITEM                                             AS item_id,     im.ITEM_DESC                                        AS item_description,     im.DEPT                                             AS dept_no,     d.DEPT_NAME                                         AS dept_name,     im.CLASS                                            AS class_no,     im.SUBCLASS                                         AS subclass_no,       td.TSF_QTY                                          AS transfer_qty,     td.SHIP_QTY                                         AS shipped_qty,     td.RECEIVED_QTY                                     AS received_qty,     (td.TSF_QTY  - NVL(td.SHIP_QTY,     0))            AS unshipped_qty,     (td.SHIP_QTY - NVL(td.RECEIVED_QTY, 0))            AS in_transit_qty,     (td.TSF_QTY  - NVL(td.RECEIVED_QTY, 0))            AS outstanding_qty,      ROUND(NVL(td.TSF_COST, 0) / NULLIF(td.TSF_QTY, 0), 4)                                                         AS unit_cost,     ROUND(         (td.TSF_QTY - NVL(td.RECEIVED_QTY, 0)) *         (NVL(td.TSF_COST, 0) / NULLIF(td.TSF_QTY, 0))     , 2)                                                AS outstanding_cost_value,       ils.STOCK_ON_HAND                                   AS from_loc_curr_soh,       p.CURR_454_MONTH                                    AS fiscal_month_454,     p.CURR_454_WEEK                                     AS fiscal_week_454,     p.CURR_454_YEAR                                     AS fiscal_year_454,     p.HALF_NO                                           AS fiscal_half,       th.CREATE_ID                                        AS created_by,     th.APPROVAL_DATE                                    AS approved_date  FROM     MFCS_RDS.RDS_WV_TSFHEAD             th     JOIN  MFCS_RDS.RDS_WV_TSFDETAIL     td   ON  th.TSF_NO        = td.TSF_NO     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER   im   ON  td.ITEM           = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS          d    ON  im.DEPT           = d.DEPT       LEFT JOIN MFCS_RDS.RDS_WV_STORE     fs   ON  th.FROM_LOC       = fs.STORE                                              AND  th.FROM_LOC_TYPE  = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH        fw   ON  th.FROM_LOC       = fw.WH                                              AND  th.FROM_LOC_TYPE  = 'W'       LEFT JOIN MFCS_RDS.RDS_WV_STORE     ts   ON  th.TO_LOC         = ts.STORE                                              AND  th.TO_LOC_TYPE    = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH        tw   ON  th.TO_LOC         = tw.WH                                              AND  th.TO_LOC_TYPE    = 'W'       LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  ils                                              ON  td.ITEM            = ils.ITEM                                              AND th.FROM_LOC        = ils.LOC                                              AND th.FROM_LOC_TYPE   = ils.LOC_TYPE       LEFT JOIN MFCS_RDS.RDS_WV_PERIOD    p    ON  TRUNC(th.DELIVERY_DATE) = TRUNC(p.VDATE)  WHERE     th.DELIVERY_DATE  < TRUNC(SYSDATE)     AND th.STATUS     IN ('A', 'S', 'IR')     AND th.DELIVERY_DATE >= ADD_MONTHS(SYSDATE, -3)    ORDER BY     (TRUNC(SYSDATE) - TRUNC(th.DELIVERY_DATE)) DESC,     th.FROM_LOC,     th.TSF_NO,     td.ITEM